INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_HOMER_ILIAD_ODYSSEY','primary text','Homer, Iliad and Odyssey (c. 750-675 BCE); Odyssey 11 (Nekyia)','reuse'),
 ('SRC_HESIOD_WORKS_DAYS','primary text','Hesiod, Works and Days (c. 700 BCE), trans. Evelyn-White','reuse'),
 ('SRC_VIRGIL_AENEID','primary text','Virgil, Aeneid (19 BCE); Book 6 (Aeneas in the underworld)','reuse')
INSERT INTO _e VALUES
 ('ENT_GRR_UNDERWORLD','The Greek Underworld (House of Hades)','Cosmological realm','Cosmological realm','Greek','underworld; realm of the dead','B','Hub entity for the structured Greek realm of the dead, the domain of Hades and Persephone, divided into regions for the dead by their merit. Composite of Homer Odyssey 11, Hesiod, and Virgil Aeneid 6; the systematized topography (rivers, fields, judges) is fullest in Virgil.'),
 ('ENT_GRR_ELYSIUM','Elysium (Elysian Fields)','Cosmological realm','Cosmological realm','Greek','blessed afterlife for heroes and the virtuous','B','The Elysian Fields, paradisal abode of heroes and the righteous dead. First named at Homer Odyssey 4.563-569 (Elysian plain, where Menelaus is destined to go); elaborated as a region of the underworld in Virgil Aeneid 6.637-678.'),
 ('ENT_GRR_ASPHODEL','The Asphodel Meadows','Cosmological realm','Cosmological realm','Greek','afterlife abode of ordinary shades','B','The Asphodel Meadow (leimon asphodelos), where the shades of the unremarkable dead wander, named at Homer Odyssey 11.539 and 24.13. The intermediate region for those neither heroic nor wicked.'),
 ('ENT_GRR_ISLES_BLEST','The Isles of the Blest (Fortunate Isles)','Cosmological realm','Cosmological realm','Greek','blessed afterlife at the edge of the world','B','The Islands of the Blessed (makaron nesoi), at the ends of the earth by deep-swirling Ocean, where Hesiod''s fourth (heroic) race dwells in untroubled bliss; Hesiod, Works and Days 167-173. Often conflated with or adjacent to Elysium.'),
 ('ENT_GRR_MOURNING_FIELDS','The Mourning Fields (Lugentes Campi)','Cosmological realm','Cosmological realm','Greek','afterlife region for those who died of love','C','The Fields of Mourning (Lugentes Campi), region of the underworld for those consumed and killed by unhappy love (e.g. Dido, Phaedra), attested at Virgil, Aeneid 6.440-444. A Roman-poetic systematization of the Greek underworld.'),
 ('ENT_GRR_PLAIN_LETHE','The Plain of Lethe','Cosmological realm','Cosmological realm','Greek','place of forgetting before rebirth','C','The plain through which the river Lethe flows, where shades destined for reincarnation drink the water of forgetfulness; Virgil, Aeneid 6.703-715 (Anchises shows Aeneas the souls by Lethe). Plato Republic 10.621 places the Plain of Lethe (pediton tes Lethes) in the eschatology of Er.'),
 ('ENT_GRR_FIELDS_PUNISHMENT','The Fields of Punishment','Cosmological realm','Cosmological realm','Greek','place of torment for the wicked dead','B','The region where the wicked are punished, bounded by the flaming river Phlegethon and overseen by Rhadamanthus; the great prison-pit of Tartarus lies below it. Virgil, Aeneid 6.548-627 (Tartarus and the punishments). Distinct from but continuous with primordial Tartarus.');
